# ---------------- writer ----------------
def main():
    assert len(CASES) == 20, len(CASES)
    ids = [c[0] for c in CASES]
    assert len(set(ids)) == 20
    written = 0
    for cid, conf, ptext, basis in CASES:
        assert 0.0 <= conf <= 1.0, cid
        assert basis.split("。")[0] and "tradition" in basis[:60], cid
        rec = {"case_id": cid, "prediction_text": ptext, "basis": basis,
               "confidence": conf, "trigger": dict(TRIG)}
        path = os.path.join(OUT, cid + ".json")
        assert not os.path.exists(path), "refuse overwrite: " + path
        with open(path, "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
        with open(path, encoding="utf-8") as f:
            back = json.load(f)
        assert list(back.keys()) == ["case_id", "prediction_text", "basis", "confidence", "trigger"], cid
        assert back["trigger"] == TRIG, cid
        written += 1
    trig_counts = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
    print("cases:", len(CASES), "written:", written, "trigger_counts:", trig_counts)

if __name__ == "__main__":
    main()
